"""Only task-generated bytes: deleted audio stays history without worker deletion.

Actual unlink is performed only by audio_cleanup.cleanup_segment on these new
fixtures. Missing-source negatives rename their generated source for retention.
No model, decoder, FFmpeg, network, worker or existing installation is used.
"""
import os
from pathlib import Path

import pytest

from scripts import audio_cleanup as cleanup
from scripts import audio_segments as audio
from scripts import transcript_results as results
from scripts.asr_sweep import SweepEngine


class Clock:
    def __init__(self):
        self.mono, self.wall = 0.0, 1000.0

    def advance(self, seconds):
        self.mono += seconds
        self.wall += seconds


def forbidden(*_args, **_kwargs):
    pytest.fail("history discovery must not load a model, recognize or clean audio")


def committed(data, *, rows=None):
    folder = data / "audio_history_2000-01-01"
    folder.mkdir(exist_ok=True)
    number, source = audio.reserve_segment(data, folder)
    with source.open("xb") as stream:
        stream.write(b"generated-cleaned-history" * 256)
        stream.flush()
        os.fsync(stream.fileno())
    audio.publish_closed(data, folder, source, number, 100 + number, 160 + number)
    rows = [{"start": 0, "end": 1, "text": "generated history"}] if rows is None else rows
    outcome = results.process_segment(data, folder, source.name, lambda _path: (rows, 60), "fake-local-model")
    assert outcome["completed_now"]
    assert results.rebuild_projection(data, folder)["projection_ready"]
    return folder, source


def text_facts(data, folder, source):
    speech, receipt, _pending = results.projection_paths(data, folder)
    paths = [results.result_path(data, folder, source.name), results.attempt_path(data, folder, source.name),
             folder / ".segments" / (source.stem + ".json"), speech, receipt]
    return {path: path.read_bytes() for path in paths}


def engine(data, clock):
    return SweepEngine(data, recognize=forbidden, prepare_model=forbidden,
                       monotonic=lambda: clock.mono, wall_time=lambda: clock.wall, scan_seconds=100)


def scan(lane, clock, *, newer_than=None):
    for _ in range(20):
        lane.step()
        completed = lane.snapshot()["scan"]["last_complete_at"]
        if completed is not None and (newer_than is None or completed > newer_than):
            return lane.snapshot()
        clock.advance(1)
    pytest.fail("generated discovery did not finish a bounded scan")


def clean(data, folder, source):
    cleanup.cleanup_segment(data, folder, source.name)
    assert not source.exists()
    facts = results.validate_success(data, folder, source.name)
    assert facts["current_result"] and facts["history_usable"] and facts["audio_cleaned"]
    assert facts["projection_ready"] and not facts["reusable"] and not facts["cleanup_eligible"]


@pytest.mark.parametrize("no_speech,pending", [(False, False), (True, False), (False, True)],
                         ids=["deleted-speech", "deleted-no-speech", "pending-after-delete"])
def test_authorized_missing_audio_is_complete_without_model_or_automatic_settlement(tmp_path, monkeypatch, no_speech, pending):
    folder, source = committed(tmp_path, rows=[] if no_speech else None)
    text = text_facts(tmp_path, folder, source)
    operation = cleanup.operation_path(tmp_path, folder, source.name)
    if pending:
        original = audio.atomic_json

        def interrupt_settlement(path, value):
            if Path(path) == operation and value.get("state") == "deleted":
                raise PermissionError("generated interruption after unlink before settlement")
            return original(path, value)

        with monkeypatch.context() as fault:
            fault.setattr(audio, "atomic_json", interrupt_settlement)
            try:
                cleanup.cleanup_segment(tmp_path, folder, source.name)
            except (OSError, ValueError):
                pass
        assert not source.exists() and audio.read_json(operation)["state"] == "pending"
    else:
        clean(tmp_path, folder, source)
    record = operation.read_bytes()
    facts = results.validate_success(tmp_path, folder, source.name)
    assert facts["current_result"] and facts["history_usable"] and facts["audio_cleaned"]
    monkeypatch.setattr(cleanup, "cleanup_segment", forbidden)
    clock, lane = Clock(), None
    try:
        lane = engine(tmp_path, clock)
        status = scan(lane, clock)
        assert status["counts"]["complete"] == 1 and status["counts"]["blocked"] == 0
        assert status["counts"]["pending"] == status["counts"]["retryable"] == 0
        assert operation.read_bytes() == record
        assert all(path.read_bytes() == value for path, value in text.items())
        assert not source.exists() and not list(tmp_path.rglob("*.tmp"))
    finally:
        if lane is not None:
            lane.close()


@pytest.mark.parametrize("fault", ["missing-without-operation", "bad-operation", "bad-intent", "bad-projection", "bad-operation-source-present"])
def test_history_evidence_and_present_source_do_not_authorize_new_work(tmp_path, monkeypatch, fault):
    folder, source = committed(tmp_path)
    operation = cleanup.operation_path(tmp_path, folder, source.name)
    retained = tmp_path / "retained-generated-source.flv"
    if fault == "missing-without-operation":
        assert source.resolve().is_relative_to(tmp_path.resolve()) and retained.resolve().is_relative_to(tmp_path.resolve())
        source.rename(retained)
    elif fault == "bad-operation-source-present":
        operation.parent.mkdir(exist_ok=True)
        operation.write_bytes(b'{"generated-bad-operation":')
    else:
        clean(tmp_path, folder, source)
        if fault == "bad-operation":
            operation.write_bytes(b'{"generated-bad-operation":')
        elif fault == "bad-intent":
            results.attempt_path(tmp_path, folder, source.name).write_bytes(b'{"generated-bad-intent":')
        else:
            _speech, receipt, _pending = results.projection_paths(tmp_path, folder)
            receipt.write_bytes(b'{"generated-bad-projection":')
    monkeypatch.setattr(cleanup, "cleanup_segment", forbidden)
    clock = Clock()
    lane = engine(tmp_path, clock)
    try:
        status = scan(lane, clock)
        present = fault == "bad-operation-source-present"
        assert status["counts"]["complete"] == int(present)
        assert status["counts"]["blocked"] == int(not present)
        assert status["counts"]["pending"] == status["counts"]["retryable"] == 0
        if fault == "missing-without-operation":
            assert retained.read_bytes() == b"generated-cleaned-history" * 256 and not operation.exists()
        if present:
            assert source.read_bytes() == b"generated-cleaned-history" * 256
        assert not list(tmp_path.rglob("*.tmp"))
    finally:
        lane.close()


@pytest.mark.parametrize("change", ["corruption", "hardlink"])
def test_cleanup_record_changes_invalidate_cached_complete_before_ttl(tmp_path, monkeypatch, change):
    folder, source = committed(tmp_path)
    clean(tmp_path, folder, source)
    operation = cleanup.operation_path(tmp_path, folder, source.name)
    monkeypatch.setattr(cleanup, "cleanup_segment", forbidden)
    clock = Clock()
    lane = engine(tmp_path, clock)
    try:
        first = scan(lane, clock)
        assert first["counts"]["complete"] == 1
        token, source_token = lane._tokens(folder, source.name)
        if change == "corruption":
            operation.write_bytes(b'{"generated-incomplete-operation":')
        else:
            os.link(operation, tmp_path / "retained-operation-hardlink.json")
        changed_token, unchanged_source = lane._tokens(folder, source.name)
        assert changed_token != token and unchanged_source == source_token
        clock.advance(10)
        assert clock.mono < lane.verify_interval
        status = scan(lane, clock, newer_than=first["scan"]["last_complete_at"])
        assert status["counts"]["complete"] == 0 and status["counts"]["blocked"] == 1
        assert not source.exists() and not list(tmp_path.rglob("*.tmp"))
    finally:
        lane.close()


def test_later_projection_and_new_segment_keep_cleaned_history_complete(tmp_path, monkeypatch):
    folder, first = committed(tmp_path)
    clean(tmp_path, folder, first)
    operation = cleanup.operation_path(tmp_path, folder, first.name)
    record = operation.read_bytes()
    same_folder, second = committed(tmp_path)
    assert same_folder == folder and int(second.stem[4:]) > int(first.stem[4:])
    facts = results.validate_success(tmp_path, folder, first.name)
    assert facts["history_usable"] and facts["audio_cleaned"] and facts["projection_ready"]
    text = text_facts(tmp_path, folder, first)
    text.update(text_facts(tmp_path, folder, second))
    monkeypatch.setattr(cleanup, "cleanup_segment", forbidden)
    clock = Clock()
    lane = engine(tmp_path, clock)
    try:
        status = scan(lane, clock)
        assert status["counts"]["complete"] == 2 and status["counts"]["blocked"] == 0
        assert operation.read_bytes() == record and not first.exists()
        assert second.read_bytes() == b"generated-cleaned-history" * 256
        assert not cleanup.operation_path(tmp_path, folder, second.name).exists()
        assert all(path.read_bytes() == value for path, value in text.items())
        assert not list(tmp_path.rglob("*.tmp"))
    finally:
        lane.close()


@pytest.mark.parametrize("damage", ["missing", "truncated"])
def test_cleaned_audio_with_damaged_speech_repairs_only_projection(tmp_path, monkeypatch, damage):
    folder, source = committed(tmp_path)
    clean(tmp_path, folder, source)
    operation = cleanup.operation_path(tmp_path, folder, source.name)
    preserved = {path: path.read_bytes() for path in (
        operation, results.result_path(tmp_path, folder, source.name),
        results.attempt_path(tmp_path, folder, source.name),
        folder / ".segments" / (source.stem + ".json"))}
    speech, _receipt, _pending = results.projection_paths(tmp_path, folder)
    retained = tmp_path / "retained-generated-speech.jsonl"
    assert speech.resolve().is_relative_to(tmp_path.resolve()) and retained.resolve().is_relative_to(tmp_path.resolve())
    speech.rename(retained)
    if damage == "truncated":
        speech.write_bytes(b'{"generated-truncated-speech":')
    facts = results.validate_success(tmp_path, folder, source.name)
    assert facts["current_result"] and facts["audio_cleaned"] and not facts["projection_ready"]
    assert not facts["history_usable"] and not facts["reusable"]
    monkeypatch.setattr(cleanup, "cleanup_segment", forbidden)
    clock = Clock()
    lane = engine(tmp_path, clock)
    try:
        status = scan(lane, clock)
        assert status["counts"]["complete"] == 1 and status["counts"]["blocked"] == 0
        assert speech.read_bytes() == retained.read_bytes()
        assert all(path.read_bytes() == value for path, value in preserved.items())
        assert not source.exists() and not list(tmp_path.rglob("*.tmp"))
    finally:
        lane.close()
